"use client";

import { useState, useMemo } from "react";
import {
    AlertTriangle,
    Clock,
    Package,
    Bell,
    Check,
    X,
    Loader2,
    Calendar,
    Download,
    Filter
} from "lucide-react";
import { useData } from "@/lib/hooks";
import ExpiryAlertsDashboard from "@/components/expiry/ExpiryAlertsDashboard";
import { generateAllExpiryAlerts } from "@/lib/expiryTracking";

export default function AlertsPage() {
    const { data: alerts, loading: alertsLoading, refetch: refetchAlerts } = useData<any[]>("/api/alerts");
    const { data: products, loading: productsLoading } = useData<any[]>("/api/products");
    const [activeTab, setActiveTab] = useState<'expiry' | 'system'>('expiry');

    const expiryAlerts = useMemo(() => {
        if (!products) return [];
        return generateAllExpiryAlerts(products);
    }, [products]);

    const resolveAlert = async (id: number) => {
        setTimeout(() => {
            console.log("Mock resolved alert:", id);
            refetchAlerts();
            alert("Alert marked as resolved!");
        }, 500);
    };

    if (alertsLoading || productsLoading) return (
        <div className="flex justify-center py-20">
            <Loader2 className="h-10 w-10 text-purple-600 animate-spin" />
        </div>
    );

    const summary = {
        total: (alerts?.length || 0) + expiryAlerts.length,
        critical: (alerts?.filter(a => a.severity === 'high' || a.severity === 'critical').length || 0) +
            expiryAlerts.filter(a => a.days <= 30).length,
        expiry: expiryAlerts.length,
        system: alerts?.length || 0,
    };

    return (
        <div className="flex flex-col gap-8 animate-fade-in-up">
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-black text-gray-900 uppercase tracking-tight">IR Alerts Center</h1>
                    <p className="text-gray-500 mt-1 font-medium">Monitoring system health and medicine life-cycles.</p>
                </div>
                <div className="flex gap-2">
                    <button className="btn-secondary flex items-center gap-2">
                        <Download className="h-4 w-4" />
                        Export Report
                    </button>
                </div>
            </div>

            {/* Summary Cards */}
            <div className="grid gap-6 md:grid-cols-4">
                {[
                    { label: "Total Alerts", value: summary.total, icon: Bell, color: "bg-purple-500", shadow: "shadow-purple-200" },
                    { label: "Critical Priority", value: summary.critical, icon: AlertTriangle, color: "bg-red-500", shadow: "shadow-red-200" },
                    { label: "Medicine Expiries", value: summary.expiry, icon: Clock, color: "bg-orange-500", shadow: "shadow-orange-200" },
                    { label: "System Health", value: "Optimal", icon: Check, color: "bg-green-500", shadow: "shadow-green-200" },
                ].map((s, i) => (
                    <div key={i} className="card-premium rounded-2xl p-6 flex items-center gap-4 border-b-4 border-gray-100">
                        <div className={`w-12 h-12 rounded-xl ${s.color} flex items-center justify-center text-white shadow-xl ${s.shadow}`}>
                            <s.icon className="h-6 w-6" />
                        </div>
                        <div>
                            <p className="text-[10px] text-gray-400 font-black uppercase tracking-widest">{s.label}</p>
                            <p className="text-2xl font-black text-gray-900">{s.value}</p>
                        </div>
                    </div>
                ))}
            </div>

            {/* Tabs */}
            <div className="flex gap-2 border-b border-gray-100">
                <button
                    onClick={() => setActiveTab('expiry')}
                    className={`px-6 py-3 text-sm font-black uppercase tracking-widest transition-all border-b-4 ${activeTab === 'expiry' ? 'border-purple-600 text-purple-600' : 'border-transparent text-gray-400 hover:text-gray-600'
                        }`}
                >
                    Expiry Alerts ({expiryAlerts.length})
                </button>
                <button
                    onClick={() => setActiveTab('system')}
                    className={`px-6 py-3 text-sm font-black uppercase tracking-widest transition-all border-b-4 ${activeTab === 'system' ? 'border-purple-600 text-purple-600' : 'border-transparent text-gray-400 hover:text-gray-600'
                        }`}
                >
                    System Alerts ({alerts?.length || 0})
                </button>
            </div>

            {activeTab === 'expiry' ? (
                <ExpiryAlertsDashboard alerts={expiryAlerts} />
            ) : (
                <div className="card-premium rounded-3xl divide-y divide-gray-50 overflow-hidden">
                    {alerts?.map((alert) => (
                        <div
                            key={alert.id}
                            className={`p-8 flex items-start gap-6 transition-all ${alert.resolved ? 'bg-gray-50/50 grayscale' : 'hover:bg-purple-50/10'}`}
                        >
                            <div className={`w-14 h-14 rounded-2xl flex items-center justify-center shadow-sm ${alert.severity === 'high' ? 'bg-red-100 text-red-600' :
                                    alert.severity === 'medium' ? 'bg-orange-100 text-orange-600' : 'bg-blue-100 text-blue-600'
                                }`}>
                                {alert.type === 'expiry' ? <Clock className="h-7 w-7" /> : <Bell className="h-7 w-7" />}
                            </div>

                            <div className="flex-1">
                                <div className="flex items-start justify-between">
                                    <div>
                                        <div className="flex items-center gap-3 mb-1">
                                            <h4 className="font-black text-gray-900 text-lg uppercase tracking-tight">{alert.message}</h4>
                                            <span className={`px-3 py-1 rounded-lg text-[10px] font-black uppercase tracking-widest ${alert.severity === 'high' ? 'bg-red-500 text-white' :
                                                    alert.severity === 'medium' ? 'bg-orange-500 text-white' : 'bg-blue-500 text-white'
                                                }`}>
                                                {alert.severity}
                                            </span>
                                        </div>
                                        <p className="text-gray-500 font-medium">Automatic system notification</p>
                                    </div>
                                    <span className="text-[10px] text-gray-400 font-black uppercase">{alert.date}</span>
                                </div>

                                {!alert.resolved && (
                                    <div className="flex gap-3 mt-6">
                                        <button
                                            onClick={() => resolveAlert(alert.id)}
                                            className="px-6 py-2.5 rounded-xl bg-gray-900 text-white text-[10px] font-black uppercase tracking-widest hover:bg-black transition-all shadow-xl shadow-gray-200"
                                        >
                                            Dismiss Alert
                                        </button>
                                    </div>
                                )}
                            </div>
                        </div>
                    ))}
                    {alerts?.length === 0 && (
                        <div className="p-20 text-center text-gray-300">
                            <Bell className="h-16 w-16 mx-auto mb-4 opacity-20" />
                            <p className="text-lg font-black uppercase tracking-tighter">Everything is running smoothly</p>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
}
